#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's quoting undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"; fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line). Idempotent. Creates ENV_FILE at mode 0600; writes through a symlink
# and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

# Procore Developer Sandbox for Safe Edge (#56). Creates the sandbox app whose service account files accepted findings
# as Procore Observations, and writes PROCORE_CLIENT_ID, PROCORE_CLIENT_SECRET, PROCORE_COMPANY_ID and
# PROCORE_PROJECT_ID to the repo-root .env (gitignored), which `bun run procore:smoke` and `bun run dev` read.
# Steps follow developers.procore.com as read on 19 Oct 2026: documentation/building-apps-create-new,
# install-version-sandbox, developer-managed-service-accounts, development-environments, oauth-client-credentials.

TOTAL_STAGES=7
LOGIN=https://login-sandbox.procore.com
API=https://sandbox.procore.com

cd "$(dirname "$0")/.."
for tool in curl jq bun; do
  command -v "$tool" >/dev/null 2>&1 || { printf '%s is required: brew install %s\n' "$tool" "$tool" >&2; exit 1; }
done

# procore_get PATH [COMPANY_ID]: GET from the sandbox API with a fresh service-account token. Errors go to stderr,
# since callers capture stdout.
procore_get() {
  local reply token
  reply=$(curl -sS --fail-with-body -X POST "$LOGIN/oauth/token" -H 'Content-Type: application/json' \
    -d "$(jq -n --arg id "$PROCORE_CLIENT_ID" --arg secret "$PROCORE_CLIENT_SECRET" \
      '{grant_type: "client_credentials", client_id: $id, client_secret: $secret}')") ||
    { warn "Procore refused the client ID and secret: $reply" >&2; return 1; }
  token=$(printf '%s' "$reply" | jq -r .access_token)
  reply=$(curl -sS --fail-with-body "$API$1" -H "Authorization: Bearer $token" ${2:+-H "Procore-Company-Id: $2"}) ||
    { warn "Procore refused GET $1: $reply" >&2; return 1; }
  printf '%s\n' "$reply"
}

banner "Procore Developer Sandbox for Safe Edge"

stage "Developer Portal account"
say "Procore apps live in the Developer Portal. A free account can build and test in its sandbox."
open_url "https://developers.procore.com"
step "Already registered? Sign in and skip ahead."
step "Otherwise select Sign Up, enter your first name, last name and email, set a password, complete the reCAPTCHA."
step "Select Create free account, then open the verification email and confirm your address."
pause "Signed in to the Developer Portal? Press Enter"

stage "Create the app"
say "Creating an app also creates its Developer Sandbox: a Procore company with a starter project."
step "Go to My Apps and select Create a New App."
step "App Name: Safe Edge (sandbox). Select Create App."
note "Creating the app accepts Procore's User Terms of Service, API Terms of Use and Privacy Notice."
step "Within a few minutes an email arrives to set your sandbox password. Set it now; stage 5 signs in with it."
pause "App created and sandbox password set? Press Enter"

stage "Give the app a service account"
say "Safe Edge signs in as the app's service account (the client-credentials grant), so the app needs one."
step "On the app page, select Create Version, then Edit Components."
step "Add the Data Connector component Service Account Authentication."
step "On that component select Manage, then Edit Configuration, and grant the project-level Observations tool"
say "  a permission that can create and edit observations (Standard or higher)."
note "Procore's docs don't name the level the Observations API needs. If procore:smoke gets a 403, raise it to Admin."
step "Select Save Version. Its Sandbox Version card shows a Sandbox Installation Key: copy it for stage 5."
pause "Version saved and installation key copied? Press Enter"

stage "OAuth credentials"
say "Adding the Data Connector component generated the app's OAuth credentials."
step "Open the app's Credentials tab and find the Developer Sandbox OAuth Credentials panel."
note "Use the sandbox pair, not the production one: sandbox tokens come from $LOGIN."
ask PROCORE_CLIENT_ID "Paste the Developer Sandbox Client ID:"
ask_secret PROCORE_CLIENT_SECRET "Paste the Developer Sandbox Client Secret:"
write_env PROCORE_CLIENT_ID "$PROCORE_CLIENT_ID"
write_env PROCORE_CLIENT_SECRET "$PROCORE_CLIENT_SECRET"

stage "Install the app in the sandbox"
say "The service account exists only once the app is installed in the sandbox company."
open_url "$API"
step "Sign in with the sandbox password you set in stage 2."
step "Go to Company Tools > Admin > App Management, then Install App > Install Custom App."
step "Paste the Sandbox Installation Key from stage 3, select Install and confirm."
step "When asked for permitted projects, choose the starter project 1234 - Sandbox Test Project."
pause "App installed with the starter project permitted? Press Enter"

stage "Company and project"
say "Checking the credentials and looking up the sandbox company..."
companies=$(procore_get /rest/v1.0/companies)
printf '%s\n' "$companies" | jq -r '.[] | "    company \(.id)  \(.name)"'
note "The ID is also in the sandbox URL once signed in: $API/<COMPANY ID>/company/home/list"
ask PROCORE_COMPANY_ID "Sandbox company ID:"
projects=$(procore_get "/rest/v1.1/projects?company_id=$PROCORE_COMPANY_ID" "$PROCORE_COMPANY_ID")
printf '%s\n' "$projects" | jq -r '.[] | "    project \(.id)  \(.name)"'
ask PROCORE_PROJECT_ID "Project ID (the Sandbox Test Project):"
types=$(procore_get "/rest/v1.0/observations/types?project_id=$PROCORE_PROJECT_ID" "$PROCORE_COMPANY_ID")
if printf '%s\n' "$types" | jq -e 'any(.[]; .name == "Safety Hazard" and .active != false)' >/dev/null; then
  say "The project has the Safety Hazard observation type that Safe Edge files findings under."
else
  warn "The project has no active Safety Hazard observation type: $(printf '%s' "$types" | jq -r 'map(.name) | join(", ")')"
  say "Add or activate it in the Company Admin tool (observation types are managed there), then re-run this wizard."
  exit 1
fi
write_env PROCORE_COMPANY_ID "$PROCORE_COMPANY_ID"
write_env PROCORE_PROJECT_ID "$PROCORE_PROJECT_ID"

stage "Smoke test"
say "bun run procore:smoke files one Observation with a photo in the sandbox and prints its ID and URL."
note "Procore does not notify assignees of observations the API creates, so nobody gets an email."
if confirm "Create the test Observation in project $PROCORE_PROJECT_ID now?"; then
  bun run procore:smoke
  pause "Press Enter to finish"
else
  SKIPPED+=("bun run procore:smoke (files one test Observation in the sandbox)")
fi

finish
